   1: #!/usr/bin/env node
   2: // ============================================================
   3: // Claude Code Replica — CLI Entry Point
   4: // ============================================================
   5: 
   6: import * as fs from "node:fs";
   7: import * as path from "node:path";
   8: import * as crypto from "node:crypto";
   9: import * as readline from "node:readline";
  10: import dotenv from "dotenv";
  11: import chalk from "chalk";
  12: 
  13: import { agentLoop } from "./agent-loop.js";
  14: import { buildSystemPrompt } from "./system-prompt.js";
  15: import { ToolRegistry } from "./tool-registry.js";
  16: import { CORE_TOOLS } from "./tools.js";
  17: import { MCPManager, discoverMCPConfigs } from "./mcp.js";
  18: import { createModelCaller, resolveProviderConfig } from "./llm-adapter.js";
  19: import { handleSlashCommand } from "./commands.js";
  20: import { expandFileRefs } from "./file-refs.js";
  21: import { HookRegistry } from "./hooks.js";
  22: import { createCliInputReader } from "./cli-input.js";
  23: import { formatCliError } from "./cli-errors.js";
  24: import {
  25:   StreamingRenderer,
  26:   renderPermissionPrompt,
  27:   renderToolResult,
  28:   renderToolStart,
  29: } from "./cli-renderer.js";
  30: import { PersistenceManager } from "./persistence.js";
  31: import type {
  32:   AskUserFn,
  33:   Message,
  34:   ModelConfig,
  35:   PermissionMode,
  36:   Tool,
  37: } from "./types.js";
  38: 
  39: // Load environment variables
  40: dotenv.config();
  41: 
  42: // --- Configuration ---
  43: 
  44: function loadConfig(): ModelConfig {
  45:   const provider = (process.env.LLM_PROVIDER || "openai") as ModelConfig["provider"];
  46:   const apiKey = process.env.LLM_API_KEY;
  47: 
  48:   if (!apiKey) {
  49:     console.error(
  50:       "Error: LLM_API_KEY is not set. Create a .env file or set the environment variable.",
  51:     );
  52:     process.exit(1);
  53:   }
  54: 
  55:   return resolveProviderConfig({
  56:     provider,
  57:     apiKey,
  58:     model: process.env.LLM_MODEL || undefined,
  59:     baseURL: process.env.LLM_BASE_URL || undefined,
  60:     maxTokens: process.env.LLM_MAX_TOKENS
  61:       ? parseInt(process.env.LLM_MAX_TOKENS)
  62:       : undefined,
  63:     temperature: process.env.LLM_TEMPERATURE
  64:       ? parseFloat(process.env.LLM_TEMPERATURE)
  65:       : undefined,
  66:   });
  67: }
  68: 
  69: // --- Workspace ---
  70: 
  71: function getWorkspaceRoot(): string {
  72:   return process.env.WORKSPACE_ROOT || process.cwd();
  73: }
  74: 
  75: const VALID_PERMISSION_MODES: PermissionMode[] = [
  76:   "default",
  77:   "acceptEdits",
  78:   "bypassPermissions",
  79:   "plan",
  80: ];
  81: 
  82: function getPermissionMode(): PermissionMode {
  83:   const mode = process.env.PERMISSION_MODE as PermissionMode | undefined;
  84:   if (mode && VALID_PERMISSION_MODES.includes(mode)) {
  85:     return mode;
  86:   }
  87:   return "default";
  88: }
  89: 
  90: // --- Load CLAUDE.md ---
  91: 
  92: function loadClaudeMd(workspaceRoot: string): string | undefined {
  93:   const claudeMdPath = path.join(workspaceRoot, "CLAUDE.md");
  94:   try {
  95:     return fs.readFileSync(claudeMdPath, "utf-8");
  96:   } catch {
  97:     return undefined;
  98:   }
  99: }
 100: 
 101: // --- Main ---
 102: 
 103: async function main() {
 104:   console.log("╔══════════════════════════════════════╗");
 105:   console.log("║   Claude Code Replica — v1.0.0      ║");
 106:   console.log("║   Local AI Coding Assistant         ║");
 107:   console.log("╚══════════════════════════════════════╝");
 108:   console.log("");
 109: 
 110:   // Load configuration
 111:   const modelConfig = loadConfig();
 112:   const workspaceRoot = getWorkspaceRoot();
 113:   const permissionMode = getPermissionMode();
 114:   const claudeMdContent = loadClaudeMd(workspaceRoot);
 115: 
 116:   console.log(`Provider: ${modelConfig.provider}`);
 117:   console.log(`Model:    ${modelConfig.model}`);
 118:   console.log(`Workspace: ${workspaceRoot}`);
 119:   console.log(`Permission mode: ${permissionMode}`);
 120:   console.log("");
 121: 
 122:   // --- Persistence ---
 123: 
 124:   const messages: Message[] = [];
 125:   const persistence = new PersistenceManager(workspaceRoot);
 126: 
 127:   // Parse --session from CLI args
 128:   const sessionArg = process.argv.find((a) => a.startsWith("--session="));
 129:   let sessionId = sessionArg?.split("=")[1];
 130: 
 131:   // If no session specified, list available ones
 132:   if (!sessionId) {
 133:     const sessions = await persistence.listSessions();
 134:     const incomplete = sessions.filter((s) => !s.completed);
 135:     if (incomplete.length > 0) {
 136:       console.log("Recent incomplete sessions:");
 137:       for (const s of incomplete.slice(0, 5)) {
 138:         console.log(
 139:           `  ${s.sessionId.slice(0, 8)}... — ${s.messageCount} msgs — ${new Date(s.updatedAt).toLocaleString()}`,
 140:         );
 141:       }
 142:       console.log(
 143:         '  Use --session=<id> to resume, or continue for a new session.',
 144:       );
 145:       console.log("");
 146:     }
 147:   }
 148: 
 149:   // Generate or resume session
 150:   if (sessionId) {
 151:     const existing = await persistence.load(sessionId);
 152:     if (existing) {
 153:       messages.push(...existing.messages);
 154:       console.log(
 155:         `Resumed session ${sessionId.slice(0, 8)}... (${existing.messageCount} messages)`,
 156:       );
 157:     } else {
 158:       console.log(
 159:         `Session ${sessionId.slice(0, 8)}... not found. Starting new session.`,
 160:       );
 161:       sessionId = persistence.generateId();
 162:     }
 163:   } else {
 164:     sessionId = persistence.generateId();
 165:   }
 166:   console.log(`Session: ${sessionId.slice(0, 8)}...`);
 167:   console.log("");
 168: 
 169:   // --- Tool Setup ---
 170: 
 171:   const toolRegistry = new ToolRegistry();
 172:   for (const tool of CORE_TOOLS) {
 173:     toolRegistry.register(tool);
 174:   }
 175: 
 176:   // MCP Setup
 177:   const mcpManager = new MCPManager();
 178:   const mcpConfigs = discoverMCPConfigs(workspaceRoot);
 179:   for (const configPath of mcpConfigs) {
 180:     await mcpManager.loadConfig(configPath);
 181:   }
 182:   for (const mcpTool of mcpManager.getAllTools()) {
 183:     toolRegistry.register(mcpTool);
 184:   }
 185: 
 186:   console.log(`Tools loaded: ${toolRegistry.enabledCount}`);
 187:   if (mcpManager.serverCount > 0) {
 188:     console.log(`MCP servers:  ${mcpManager.serverCount}`);
 189:   }
 190:   console.log("");
 191: 
 192:   // --- System Prompt ---
 193: 
 194:   const systemPrompt = buildSystemPrompt({
 195:     workspaceRoot,
 196:     tools: toolRegistry.getEnabledTools(),
 197:     claudeMdContent,
 198:   });
 199: 
 200:   // --- Model Caller ---
 201: 
 202:   const callModel = createModelCaller(modelConfig);
 203: 
 204:   // --- Conversation ---
 205: 
 206:   const tools = toolRegistry.getEnabledTools();
 207: 
 208:   // --- Hooks ---
 209:   // Empty by default. Register PreToolUse/PostToolUse hooks here (or load
 210:   // them from project config) to intercept, block, or rewrite tool calls.
 211:   const hooks = new HookRegistry();
 212: 
 213:   // --- REPL ---
 214: 
 215:   const rl = readline.createInterface({
 216:     input: process.stdin,
 217:     output: process.stdout,
 218:   });
 219: 
 220:   const inputReader = createCliInputReader(rl);
 221:   const { askQuestion, readInput } = inputReader;
 222: 
 223:   // Tool+target combos the user chose to "always" allow this session.
 224:   const alwaysAllow = new Set<string>();
 225:   const permissionKey = (toolName: string, input: Record<string, unknown>): string => {
 226:     const target =
 227:       (typeof input.filePath === "string" && input.filePath) ||
 228:       (typeof input.command === "string" && input.command) ||
 229:       (typeof input.url === "string" && input.url) ||
 230:       "";
 231:     return `${toolName}::${target}`;
 232:   };
 233: 
 234:   // Permission prompt callback. Reuses the same readline interface; during a
 235:   // loop the main REPL is awaiting, so there's no stdin contention.
 236:   const askUser: AskUserFn = async (tool, input, riskHint) => {
 237:     const key = permissionKey(tool.name, input);
 238:     // Already approved as "always" for this tool+target this session.
 239:     if (alwaysAllow.has(key)) return true;
 240: 
 241:     renderPermissionPrompt(tool.name, input, riskHint);
 242:     const raw = await askQuestion("     > ");
 243:     // EOF while awaiting a permission decision → treat as deny (safe default).
 244:     if (raw === null) return false;
 245:     const answer = raw.trim().toLowerCase();
 246: 
 247:     if (answer === "a" || answer === "always") {
 248:       alwaysAllow.add(key);
 249:       return true;
 250:     }
 251:     return answer === "y" || answer === "yes";
 252:   };
 253: 
 254:   console.log('Type your request, /help for commands (or "exit" to quit):\n');
 255: 
 256:   // eslint-disable-next-line no-constant-condition
 257:   while (true) {
 258:     const userInput = await readInput();
 259: 
 260:     // null = stdin closed (EOF / Ctrl+D). Exit the REPL cleanly.
 261:     if (userInput === null) break;
 262:     if (!userInput.trim()) continue;
 263:     if (userInput.toLowerCase() === "exit") break;
 264: 
 265:     // Local slash commands run before anything is sent to the model.
 266:     if (userInput.startsWith("/")) {
 267:       const result = await handleSlashCommand(userInput, {
 268:         messages,
 269:         modelConfig,
 270:         callModel,
 271:         workspaceRoot,
 272:         sessionId: sessionId!,
 273:       });
 274:       if (result.exit) break;
 275:       if (result.handled) continue;
 276:     }
 277: 
 278:     // Expand @file references into context attachments.
 279:     const { attachments, notes } = expandFileRefs(userInput, workspaceRoot);
 280:     for (const note of notes) console.log(chalk.gray(note));
 281: 
 282:     const contentText =
 283:       attachments.length > 0
 284:         ? `${userInput}\n\n${attachments.join("\n\n")}`
 285:         : userInput;
 286: 
 287:     // Add user message
 288:     messages.push({
 289:       role: "user",
 290:       content: [{ type: "text", text: contentText }],
 291:     });
 292: 
 293:     // Per-turn abort handling: first Ctrl+C aborts the current turn and
 294:     // returns to the prompt; a second (at the idle prompt) exits.
 295:     const controller = new AbortController();
 296:     const onSigint = () => {
 297:       controller.abort("用户中断");
 298:     };
 299:     process.on("SIGINT", onSigint);
 300: 
 301:     // Run agent loop
 302:     const loop = agentLoop(
 303:       messages,
 304:       tools,
 305:       callModel,
 306:       modelConfig,
 307:       {
 308:         systemPrompt,
 309:         maxTurns: 50,
 310:         toolContext: {
 311:           workspaceRoot,
 312:           sessionId: sessionId!,
 313:           permissionMode,
 314:           modelConfig,
 315:         },
 316:         askUser,
 317:         abortSignal: controller.signal,
 318:         hooks,
 319:       },
 320:     );
 321: 
 322:     let lastText = "";
 323:     let turnInputTokens = 0;
 324:     let turnOutputTokens = 0;
 325:     const renderer = new StreamingRenderer();
 326: 
 327:     for await (const event of loop) {
 328:       switch (event.type) {
 329:         case "text_delta":
 330:           renderer.write(event.delta);
 331:           lastText += event.delta;
 332:           break;
 333: 
 334:         case "tool_use":
 335:           renderer.flush();
 336:           renderToolStart(event.name, event.input);
 337:           break;
 338: 
 339:         case "tool_results":
 340:           renderer.flush();
 341:           for (const result of event.results) {
 342:             renderToolResult(result);
 343:           }
 344:           // Auto-save after tool execution
 345:           persistence.save(sessionId!, messages).catch(() => {});
 346:           break;
 347: 
 348:         case "compacting":
 349:           renderer.flush();
 350:           console.log("\n  📦 Compacting context...");
 351:           break;
 352: 
 353:         case "usage":
 354:           turnInputTokens += event.usage.input_tokens;
 355:           turnOutputTokens += event.usage.output_tokens;
 356:           break;
 357: 
 358:         case "error":
 359:           renderer.flush();
 360:           console.error(`\n  ⚠️ ${formatCliError(event.error)}`);
 361:           break;
 362: 
 363:         case "done":
 364:           renderer.flush();
 365:           if (turnInputTokens || turnOutputTokens) {
 366:             console.log(
 367:               chalk.gray(
 368:                 `\n  [tokens: ${turnInputTokens} in / ${turnOutputTokens} out]`,
 369:               ),
 370:             );
 371:           }
 372:           // Final assistant text was added to messages in the loop
 373:           persistence.save(sessionId!, messages).catch(() => {});
 374:           break;
 375: 
 376:         case "aborted":
 377:           renderer.flush();
 378:           console.log(`\n  ⏹️ Aborted: ${event.reason}`);
 379:           break;
 380:       }
 381:     }
 382: 
 383:     // Detach this turn's SIGINT handler so handlers don't stack up.
 384:     process.removeListener("SIGINT", onSigint);
 385: 
 386:     console.log(""); // New line after response
 387:   }
 388: 
 389:   // Cleanup
 390:   rl.close();
 391:   await persistence.save(sessionId!, messages, { completed: true });
 392:   await mcpManager.disconnectAll();
 393:   console.log("\nGoodbye!");
 394: }
 395: 
 396: main().catch((error) => {
 397:   console.error("Fatal error:", formatCliError(error));
 398:   process.exit(1);
 399: });
 400: 
