   1: // ============================================================
   2: // Agent Loop — The heart of the system
   3: // ============================================================
   4: 
   5: import type {
   6:   AskUserFn,
   7:   HookRunner,
   8:   LoopEvent,
   9:   LoopOptions,
  10:   Message,
  11:   ModelCaller,
  12:   ModelConfig,
  13:   Tool,
  14:   ToolCall,
  15:   ToolContext,
  16:   ToolExecutionResult,
  17: } from "./types.js";
  18: import { checkPermission } from "./permissions.js";
  19: 
  20: // Default approver used when the caller (CLI) does not supply one — e.g.
  21: // sub-agents and tests. Preserves backward-compatible "allow" behavior;
  22: // plan-mode blocking is still enforced inside checkPermission().
  23: const defaultAskUser: AskUserFn = async () => true;
  24: 
  25: // --- Agent Loop (Async Generator) ---
  26: 
  27: export async function* agentLoop(
  28:   messages: Message[],
  29:   tools: Tool[],
  30:   callModel: ModelCaller,
  31:   modelConfig: ModelConfig,
  32:   options: LoopOptions,
  33: ): AsyncGenerator<LoopEvent> {
  34:   const {
  35:     maxTurns = 50,
  36:     autoCompactThreshold = 150_000,
  37:     systemPrompt,
  38:     abortSignal,
  39:     toolContext,
  40:     askUser = defaultAskUser,
  41:     hooks,
  42:   } = options;
  43: 
  44:   // Build the full ToolContext from caller-provided values, falling back to
  45:   // sensible defaults. This replaces the previously hardcoded context.
  46:   const baseContext: ToolContext = {
  47:     workspaceRoot: toolContext?.workspaceRoot ?? process.cwd(),
  48:     sessionId: toolContext?.sessionId ?? "default",
  49:     permissionMode: toolContext?.permissionMode ?? "default",
  50:     modelConfig: toolContext?.modelConfig ?? modelConfig,
  51:   };
  52: 
  53:   let turnCount = 0;
  54:   let totalTokens = 0;
  55: 
  56:   while (turnCount < maxTurns) {
  57:     // Check for abort
  58:     if (abortSignal?.aborted) {
  59:       yield { type: "aborted", reason: abortSignal.reason };
  60:       return;
  61:     }
  62: 
  63:     // === STEP 1: Check if compaction is needed ===
  64:     if (estimateTokens(messages) > autoCompactThreshold) {
  65:       yield { type: "compacting" };
  66:       messages = await autoCompact(messages, callModel, modelConfig);
  67:       yield { type: "compacted", summary: "Context compressed" };
  68:     }
  69: 
  70:     // === STEP 2: Call the LLM ===
  71:     yield { type: "thinking" };
  72: 
  73:     let textBuffer = "";
  74:     const toolCalls: ToolCall[] = [];
  75:     let usage: { input_tokens: number; output_tokens: number } | null = null;
  76: 
  77:     try {
  78:       for await (const event of callModel(
  79:         messages,
  80:         tools,
  81:         systemPrompt,
  82:         modelConfig,
  83:       )) {
  84:         switch (event.type) {
  85:           case "text_delta":
  86:             textBuffer += event.delta;
  87:             yield { type: "text_delta", delta: event.delta };
  88:             break;
  89: 
  90:           case "tool_use":
  91:             toolCalls.push({
  92:               id: event.id,
  93:               type: "function",
  94:               function: {
  95:                 name: event.name,
  96:                 arguments: JSON.stringify(event.input),
  97:               },
  98:             });
  99:             yield {
 100:               type: "tool_use",
 101:               name: event.name,
 102:               input: event.input,
 103:             };
 104:             break;
 105: 
 106:           case "done":
 107:             usage = event.usage;
 108:             totalTokens += usage.input_tokens + usage.output_tokens;
 109:             yield { type: "usage", usage };
 110:             break;
 111: 
 112:           case "error":
 113:             // Handle recoverable errors
 114:             const recovery = await handleModelError(
 115:               event.error,
 116:               messages,
 117:               callModel,
 118:               modelConfig,
 119:             );
 120:             if (recovery === "retry") continue;
 121:             if (recovery === "abort") {
 122:               yield { type: "error", error: event.error };
 123:               return;
 124:             }
 125:             break;
 126:         }
 127:       }
 128:     } catch (error) {
 129:       yield { type: "error", error };
 130:       return;
 131:     }
 132: 
 133:     // === STEP 3: If no tool calls, we're done ===
 134:     if (toolCalls.length === 0) {
 135:       // Save the assistant's text response to message history
 136:       if (textBuffer) {
 137:         messages.push({
 138:           role: "assistant",
 139:           content: textBuffer,
 140:         });
 141:       }
 142:       yield {
 143:         type: "done",
 144:         finishReason: "end_turn",
 145:         turns: turnCount,
 146:       };
 147:       return;
 148:     }
 149: 
 150:     // === STEP 4: Add assistant message to history ===
 151:     messages.push({
 152:       role: "assistant",
 153:       content: textBuffer || null,
 154:       tool_calls: toolCalls,
 155:     });
 156: 
 157:     // === STEP 5: Execute tool calls (parallel for safe ones) ===
 158:     const toolResults = await executeToolCalls(
 159:       toolCalls,
 160:       tools,
 161:       baseContext,
 162:       askUser,
 163:       abortSignal,
 164:       hooks,
 165:     );
 166: 
 167:     // === STEP 6: Add tool results to history ===
 168:     for (let i = 0; i < toolCalls.length; i++) {
 169:       messages.push({
 170:         role: "tool",
 171:         tool_call_id: toolCalls[i].id,
 172:         name: toolCalls[i].function.name,
 173:         content: toolResults[i].formatted,
 174:       });
 175:     }
 176: 
 177:     // Tool results may carry images (e.g. Read on a PNG/PDF). Both providers
 178:     // accept images only in user content, so inject them as a follow-up user
 179:     // message right after the tool results that produced them.
 180:     const images = toolResults.flatMap((r) => r.result?.images ?? []);
 181:     if (images.length > 0) {
 182:       messages.push({
 183:         role: "user",
 184:         content: [
 185:           { type: "text", text: "Attached image(s) from the tool result above:" },
 186:           ...images,
 187:         ],
 188:       });
 189:     }
 190: 
 191:     yield { type: "tool_results", results: toolResults };
 192: 
 193:     turnCount++;
 194:   }
 195: 
 196:   // Max turns reached
 197:   yield {
 198:     type: "done",
 199:     finishReason: "max_turns",
 200:     turns: turnCount,
 201:     message: "Maximum turns reached. Continue?",
 202:   };
 203: }
 204: 
 205: // --- Tool Call Execution ---
 206: 
 207: async function executeToolCalls(
 208:   toolCalls: ToolCall[],
 209:   tools: Tool[],
 210:   context: ToolContext,
 211:   askUser: AskUserFn,
 212:   abortSignal?: AbortSignal,
 213:   hooks?: HookRunner,
 214: ): Promise<ToolExecutionResult[]> {
 215:   // Separate into parallel-safe and serial groups
 216:   const parallelCalls: ToolCall[] = [];
 217:   const serialCalls: ToolCall[] = [];
 218: 
 219:   for (const call of toolCalls) {
 220:     const tool = tools.find((t) => t.name === call.function.name);
 221:     if (!tool) {
 222:       serialCalls.push(call);
 223:       continue;
 224:     }
 225:     if (tool.isConcurrencySafe()) {
 226:       parallelCalls.push(call);
 227:     } else {
 228:       serialCalls.push(call);
 229:     }
 230:   }
 231: 
 232:   const results: ToolExecutionResult[] = [];
 233: 
 234:   // Execute parallel-safe calls simultaneously
 235:   if (parallelCalls.length > 0) {
 236:     const parallelResults = await Promise.all(
 237:       parallelCalls.map((call) =>
 238:         executeSingleTool(call, tools, context, askUser, hooks),
 239:       ),
 240:     );
 241:     results.push(...parallelResults);
 242:   }
 243: 
 244:   // Execute serial calls one at a time
 245:   for (const call of serialCalls) {
 246:     // Allow long serial sequences to stop early on abort.
 247:     if (abortSignal?.aborted) {
 248:       results.push({
 249:         toolName: call.function.name,
 250:         error: "Aborted",
 251:         formatted: `Aborted before executing ${call.function.name}.`,
 252:       });
 253:       continue;
 254:     }
 255:     const result = await executeSingleTool(call, tools, context, askUser, hooks);
 256:     results.push(result);
 257:   }
 258: 
 259:   return results;
 260: }
 261: 
 262: async function executeSingleTool(
 263:   toolCall: ToolCall,
 264:   tools: Tool[],
 265:   context: ToolContext,
 266:   askUser: AskUserFn,
 267:   hooks?: HookRunner,
 268: ): Promise<ToolExecutionResult> {
 269:   const tool = tools.find((t) => t.name === toolCall.function.name);
 270: 
 271:   if (!tool) {
 272:     return {
 273:       toolName: toolCall.function.name,
 274:       error: `Unknown tool: ${toolCall.function.name}`,
 275:       formatted: `Error: Tool "${toolCall.function.name}" is not available.`,
 276:     };
 277:   }
 278: 
 279:   try {
 280:     let input: Record<string, unknown>;
 281:     try {
 282:       input = JSON.parse(toolCall.function.arguments);
 283:     } catch {
 284:       return {
 285:         toolName: tool.name,
 286:         error: "Invalid JSON arguments",
 287:         formatted: `Error: Failed to parse arguments for ${tool.name}`,
 288:       };
 289:     }
 290: 
 291:     // === PreToolUse hook (before permission + side effects) ===
 292:     if (hooks) {
 293:       const pre = await hooks.runPre({ toolName: tool.name, input });
 294:       if (pre.block) {
 295:         const reason = pre.reason ?? "blocked by hook";
 296:         return {
 297:           toolName: tool.name,
 298:           error: reason,
 299:           formatted: `工具被 hook 拦截: ${reason}`,
 300:         };
 301:       }
 302:       if (pre.input) input = pre.input;
 303:     }
 304: 
 305:     // === Permission check (before any side effect) ===
 306:     const permission = await checkPermission(tool, input, context, {
 307:       askUser,
 308:     });
 309:     if (!permission.allowed) {
 310:       const reason = permission.reason ?? "denied by permission policy";
 311:       return {
 312:         toolName: tool.name,
 313:         error: reason,
 314:         formatted: `权限被拒绝: ${reason}`,
 315:       };
 316:     }
 317: 
 318:     const startTime = Date.now();
 319:     let result = await tool.call(input, context);
 320:     const duration = Date.now() - startTime;
 321: 
 322:     // === PostToolUse hook (may rewrite the result) ===
 323:     if (hooks) {
 324:       const post = await hooks.runPost({ toolName: tool.name, input, result });
 325:       if (post.result) result = post.result;
 326:     }
 327: 
 328:     return {
 329:       toolName: tool.name,
 330:       result,
 331:       formatted: tool.formatResult({
 332:         ...result,
 333:         metadata: { ...result.metadata, durationMs: duration },
 334:       }),
 335:       durationMs: duration,
 336:     };
 337:   } catch (error) {
 338:     const message = error instanceof Error ? error.message : String(error);
 339:     return {
 340:       toolName: tool.name,
 341:       error: message,
 342:       formatted: `Error executing ${tool.name}: ${message}`,
 343:     };
 344:   }
 345: }
