 168:   | { type: "thinking"; delta?: string }
 169:   | {
 170:       type: "done";
 171:       usage: { input_tokens: number; output_tokens: number };
 172:       finish_reason: string;
 173:     }
 174:   | { type: "error"; error: Error };
