 176: // --- Agent Loop ---
 177: 
 178: export type LoopEvent =
 179:   | { type: "text_delta"; delta: string }
 180:   | { type: "tool_use"; name: string; input: Record<string, unknown> }
 181:   | { type: "tool_results"; results: ToolExecutionResult[] }
 182:   | { type: "thinking" }
 183:   | { type: "compacting" }
 184:   | { type: "compacted"; summary: string }
 185:   | {
 186:       type: "usage";
 187:       usage: { input_tokens: number; output_tokens: number };
 188:     }
 189:   | { type: "error"; error: unknown }
 190:   | {
 191:       type: "done";
 192:       finishReason: "end_turn" | "max_turns";
 193:       turns: number;
 194:       message?: string;
 195:     }
 196:   | { type: "aborted"; reason: string };
 197: 
 198: export interface ToolExecutionResult {
 199:   toolName: string;
 200:   result?: ToolResult;
 201:   error?: string;
 202:   formatted: string;
 203:   durationMs?: number;
 204: }
 205: 
 206: export interface LoopOptions {
 207:   maxTurns?: number;
 208:   autoCompactThreshold?: number;
 209:   systemPrompt: string;
 210:   abortSignal?: AbortSignal;
 211:   /** Partial context to thread into each tool call (sessionId, workspaceRoot, permissionMode). */
 212:   toolContext?: Partial<ToolContext>;
 213:   /** Callback to prompt the user when a tool requires confirmation. */
 214:   askUser?: AskUserFn;
 215:   /** Optional hook registry to intercept tool calls (PreToolUse/PostToolUse). */
 216:   hooks?: HookRunner;
 217: }
 218: 
 219: /** Structural type for the hook registry — see src/hooks.ts. */
 220: export interface HookRunner {
 221:   runPre(payload: {
 222:     toolName: string;
 223:     input: Record<string, unknown>;
 224:   }): Promise<{
 225:     block?: boolean;
 226:     reason?: string;
 227:     input?: Record<string, unknown>;
 228:   }>;
 229:   runPost(payload: {
 230:     toolName: string;
 231:     input: Record<string, unknown>;
 232:     result: ToolResult;
 233:   }): Promise<{ result?: ToolResult }>;
 234: }
 235: 
 236: /** Prompts the user to approve a destructive/dangerous tool call. */
 237: export type AskUserFn = (
 238:   tool: Tool,
 239:   input: Record<string, unknown>,
 240:   riskHint?: string,
 241: ) => Promise<boolean>;
 242: 
 243: // --- Model Caller ---
 244: 
 245: export type ModelCaller = (
 246:   messages: Message[],
 247:   tools: Tool[],
 248:   systemPrompt: string,
 249:   config: ModelConfig,
 250: ) => AsyncGenerator<StreamEvent>;
