 472:       },
 473:     },
 474:     required: ["filePath", "edits"],
 475:   },
 476:   isReadOnly: false,
 477:   isConcurrencySafe: false, // Same file — must be serial
 478: 
 479:   async call(input, context): Promise<ToolResult> {
 480:     const resolution = resolveInWorkspace(input.filePath, context.workspaceRoot);
 481:     if (!resolution.ok) {
 482:       return { content: "", error: resolution.error };
 483:     }
 484:     const filePath = resolution.path;
 485: 
 486:     if (isBlockedPath(filePath)) {
 487:       return {
 488:         content: "",
 489:         error: `Access denied: "${input.filePath}" is a blocked path`,
 490:       };
 491:     }
 492: 
 493:     if (!Array.isArray(input.edits) || input.edits.length === 0) {
 494:       return { content: "", error: "edits must be a non-empty array" };
