 864: // ============================================================
 865: // Helpers
 866: // ============================================================
 867: 
 868: /**
 869:  * Resolve a user-supplied path against the workspace root and confirm it
 870:  * stays inside the workspace. Returns the absolute path on success, or an
 871:  * error string on rejection.
 872:  *
 873:  * Guards two escapes the previous `startsWith(workspaceRoot)` check missed:
 874:  *  1. Prefix aliasing — "/proj" must not match a sibling "/proj-evil".
 875:  *     We compare against `workspaceRoot + path.sep` (and allow the root
 876:  *     itself).
 877:  *  2. Absolute-path override — `path.resolve(root, "/etc/passwd")` discards
 878:  *     the root and returns "/etc/passwd". We resolve, then re-verify
 879:  *     containment, so an absolute input outside the workspace is rejected.
 880:  */
 881: function resolveInWorkspace(
 882:   inputPath: string,
 883:   workspaceRoot: string,
 884: ): { ok: true; path: string } | { ok: false; error: string } {
 885:   const root = path.resolve(workspaceRoot);
 886:   const resolved = path.resolve(root, inputPath);
 887: 
 888:   if (resolved !== root && !resolved.startsWith(root + path.sep)) {
 889:     return {
 890:       ok: false,
 891:       error: `Access denied: "${inputPath}" is outside workspace`,
 892:     };
 893:   }
 894:   return { ok: true, path: resolved };
 895: }
 896: 
 897: function isBinary(buffer: Buffer): boolean {
 898:   // Check first 8KB for null bytes (common binary indicator)
 899:   const sampleSize = Math.min(buffer.length, 8192);
 900:   for (let i = 0; i < sampleSize; i++) {
 901:     if (buffer[i] === 0) return true;
 902:   }
 903:   return false;
 904: }
 905: 
 906: function formatSize(bytes: number): string {
 907:   if (bytes < 1024) return `${bytes} B`;
 908:   if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
 909:   return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
 910: }
 911: 
 912: function generateSimpleDiff(oldStr: string, newStr: string): string {
 913:   const oldLines = oldStr.split("\n");
 914:   const newLines = newStr.split("\n");
 915: 
 916:   let diff = "";
 917:   for (const line of oldLines) {
 918:     if (!newLines.includes(line)) {
 919:       diff += `- ${line}\n`;
 920:     }
 921:   }
 922:   for (const line of newLines) {
 923:     if (!oldLines.includes(line)) {
 924:       diff += `+ ${line}\n`;
 925:     }
 926:   }
 927: 
 928:   return diff || "(whitespace-only change)";
 929: }
 930: 
 931: /**
 932:  * Replace every occurrence of `oldStr` with `newStr` using index-based
 933:  * splicing. Unlike String.replaceAll, this treats both strings as literal
 934:  * text — no special-pattern interpretation in the replacement.
 935:  */
 936: function spliceAll(content: string, oldStr: string, newStr: string): string {
 937:   if (oldStr === "") return content;
 938:   let result = "";
 939:   let pos = 0;
 940:   let idx: number;
 941:   while ((idx = content.indexOf(oldStr, pos)) !== -1) {
 942:     result += content.slice(pos, idx) + newStr;
 943:     pos = idx + oldStr.length;
 944:   }
 945:   result += content.slice(pos);
 946:   return result;
 947: }
 948: 
 949: /** Current mtimeMs of a file, or undefined if it doesn't exist. */
 950: function statMtimeMs(filePath: string): number | undefined {
 951:   try {
 952:     return fs.statSync(filePath).mtimeMs;
 953:   } catch {
 954:     return undefined;
 955:   }
 956: }
 957: 
 958: // Max bytes for an inline image/PDF (base64 inflates ~33%, so keep modest).
 959: const MAX_IMAGE_BYTES = 5 * 1024 * 1024;
 960: 
 961: // Extensions the Anthropic/OpenAI vision APIs accept as image/document blocks.
 962: const IMAGE_MEDIA_TYPES: Record<string, string> = {
 963:   ".png": "image/png",
 964:   ".jpg": "image/jpeg",
 965:   ".jpeg": "image/jpeg",
 966:   ".gif": "image/gif",
 967:   ".webp": "image/webp",
 968:   ".pdf": "application/pdf",
 969: };
 970: 
 971: /** Return the media type for a multimodal-readable file, or undefined. */
 972: function imageMediaType(filePath: string): string | undefined {
