   1: // ============================================================
   2: // Task Tool — Sub-agent system for complex multi-step tasks
   3: // ============================================================
   4: // Spawns an independent sub-agent with a configurable tool set and
   5: // isolated context window. Sub-agent types come from the registry
   6: // (src/subagents.ts). Concurrent sub-agents are capped by a semaphore
   7: // so a fan-out of task calls can't exhaust the model's rate limit.
   8: // ============================================================
   9: 
  10: import type { Tool, ToolResult, Message } from "./types.js";
  11: import { createTool } from "./tool-registry.js";
  12: import { agentLoop } from "./agent-loop.js";
  13: import { createModelCaller } from "./llm-adapter.js";
  14: import {
  15:   getSubagentType,
  16:   listSubagentNames,
  17:   resolveSubagentTools,
  18: } from "./subagents.js";
  19: 
  20: // --- Constants ---
  21: 
  22: const SUBAGENT_MAX_TURNS = 10;
  23: const SUBAGENT_COMPACT_THRESHOLD = 50_000;
  24: 
  25: // Max sub-agents running at once. A turn can request many `task` calls
  26: // (they're concurrency-safe), so without a cap a wide fan-out would hit
  27: // the provider all at once. Override via TASK_MAX_CONCURRENCY.
  28: const MAX_CONCURRENCY = (() => {
  29:   const raw = Number(process.env.TASK_MAX_CONCURRENCY);
  30:   return Number.isInteger(raw) && raw > 0 ? raw : 3;
  31: })();
  32: 
  33: // --- Input ---
  34: 
  35: interface TaskInput {
  36:   description: string;
  37:   prompt: string;
  38:   subagent_name: string;
  39:   [key: string]: unknown;
  40: }
  41: 
  42: // Lazy load sub-agent tools to break circular dependency with tools.ts.
  43: // tools.ts imports TaskTool -> task-tool.ts imports tools classes -> cycle!
  44: let _coreTools: Tool[] | null = null;
  45: async function getCoreTools(): Promise<Tool[]> {
  46:   if (!_coreTools) {
  47:     const { ReadTool, GlobTool, GrepTool, BashTool, WriteTool, EditTool } =
  48:       await import("./tools.js");
  49:     _coreTools = [ReadTool, GlobTool, GrepTool, BashTool, WriteTool, EditTool];
  50:   }
  51:   return _coreTools;
  52: }
  53: 
  54: // --- Concurrency semaphore ---
  55: 
  56: let activeCount = 0;
  57: const waitQueue: Array<() => void> = [];
  58: 
  59: async function acquireSlot(): Promise<void> {
  60:   if (activeCount < MAX_CONCURRENCY) {
  61:     activeCount++;
  62:     return;
  63:   }
  64:   await new Promise<void>((resolve) => waitQueue.push(resolve));
  65:   activeCount++;
  66: }
  67: 
  68: function releaseSlot(): void {
  69:   activeCount--;
  70:   const next = waitQueue.shift();
  71:   if (next) next();
  72: }
  73: 
  74: // --- Tool ---
  75: 
  76: export const TaskTool: Tool = createTool<TaskInput>({
  77:   name: "task",
  78:   description:
  79:     "Launch a sub-agent to handle complex, multi-step tasks autonomously",
  80:   promptDescription:
  81:     "Launch a sub-agent to handle complex, multi-step tasks. " +
  82:     "Provide description (short summary), prompt (detailed instructions), and subagent_name. " +
  83:     `Available sub-agent types: ${listSubagentNames().join(", ")}. ` +
  84:     "code-explorer/code-reviewer are read-only; general can modify files. " +
  85:     "Use this for broad exploration, review, or research where intermediate " +
  86:     "tool results don't need user review. Multiple sub-agents run concurrently " +
  87:     `(capped at ${MAX_CONCURRENCY}).`,
  88:   inputSchema: {
  89:     type: "object",
  90:     properties: {
  91:       description: {
  92:         type: "string",
  93:         description: "A short (3-5 word) description of the task",
  94:       },
  95:       prompt: {
  96:         type: "string",
  97:         description:
  98:           "The detailed task for the sub-agent to perform. Be specific about what to find or do.",
  99:       },
 100:       subagent_name: {
 101:         type: "string",
 102:         description: "The type of sub-agent to launch.",
 103:         enum: listSubagentNames(),
 104:         default: "code-explorer",
 105:       },
 106:     },
 107:     required: ["description", "prompt", "subagent_name"],
 108:   },
 109:   isReadOnly: false,
 110:   isConcurrencySafe: true,
 111: 
 112:   async call(input, context): Promise<ToolResult> {
 113:     const description = input.description?.trim();
 114:     const prompt = input.prompt?.trim();
 115:     const subagentName = input.subagent_name || "code-explorer";
 116: 
 117:     // --- Validation ---
 118: 
 119:     if (!description) {
 120:       return { content: "", error: "description is required" };
 121:     }
 122:     if (!prompt) {
 123:       return { content: "", error: "prompt is required" };
 124:     }
 125:     const subagentType = getSubagentType(subagentName);
 126:     if (!subagentType) {
 127:       return {
 128:         content: "",
 129:         error: `Unknown subagent type: "${subagentName}". Allowed: ${listSubagentNames().join(", ")}`,
 130:       };
 131:     }
 132:     if (!context.modelConfig) {
 133:       return {
 134:         content: "",
 135:         error:
 136:           "Task tool requires modelConfig in context. The CLI must provide this.",
 137:       };
 138:     }
 139: 
 140:     // --- Setup sub-agent ---
 141: 
 142:     const subMessages: Message[] = [
 143:       {
 144:         role: "user",
 145:         content: [{ type: "text", text: prompt }],
 146:       },
 147:     ];
 148: 
 149:     const subCaller = createModelCaller(context.modelConfig);
 150:     const subSystemPrompt = [
 151:       subagentType.systemPrompt,
 152:       "",
 153:       `Your task: ${description}`,
 154:     ].join("\n");
 155: 
 156:     // --- Run sub-agent loop (under the concurrency cap) ---
 157: 
 158:     const startTime = Date.now();
 159:     const outputChunks: string[] = [];
 160:     let toolCallCount = 0;
 161:     let errorMessage: string | undefined;
 162: 
 163:     await acquireSlot();
 164:     try {
 165:       const coreTools = await getCoreTools();
 166:       const subagentTools = resolveSubagentTools(subagentType, coreTools);
 167:       const loop = agentLoop(
 168:         subMessages,
 169:         subagentTools,
 170:         subCaller,
 171:         context.modelConfig,
 172:         {
 173:           systemPrompt: subSystemPrompt,
 174:           maxTurns: subagentType.maxTurns ?? SUBAGENT_MAX_TURNS,
 175:           autoCompactThreshold: SUBAGENT_COMPACT_THRESHOLD,
 176:           // Run sub-agent tools in the same workspace/session as the parent.
 177:           toolContext: {
 178:             workspaceRoot: context.workspaceRoot,
 179:             sessionId: context.sessionId,
 180:             permissionMode: context.permissionMode,
 181:             modelConfig: context.modelConfig,
 182:           },
 183:         },
 184:       );
 185: 
 186:       for await (const event of loop) {
 187:         switch (event.type) {
 188:           case "text_delta":
 189:             outputChunks.push(event.delta);
 190:             break;
 191:           case "tool_use":
 192:             toolCallCount++;
 193:             break;
 194:           case "aborted":
 195:             errorMessage = event.reason;
 196:             break;
 197:           case "error":
 198:             errorMessage = String(event.error);
 199:             break;
 200:           default:
 201:             // done / thinking / tool_results / usage / compacting — silent
 202:             break;
 203:         }
 204:       }
 205:     } catch (error: any) {
 206:       errorMessage = error.message || String(error);
 207:     } finally {
 208:       releaseSlot();
 209:     }
 210: 
 211:     const duration = Date.now() - startTime;
 212:     const output = outputChunks.join("").trim();
 213: 
 214:     if (errorMessage && !output) {
 215:       return {
 216:         content: "",
 217:         error: `Sub-agent failed: ${errorMessage}`,
 218:         metadata: { durationMs: duration },
 219:       };
 220:     }
 221: 
 222:     const header = [
 223:       `[Sub-agent "${subagentName}" completed]`,
 224:       `Task: ${description}`,
 225:       `Tool calls: ${toolCallCount}`,
 226:       `Duration: ${(duration / 1000).toFixed(1)}s`,
 227:       ``,
 228:       `--- Findings ---`,
 229:       ``,
 230:     ].join("\n");
 231: 
 232:     return {
 233:       content: header + (output || "(no output)"),
 234:       truncated: false,
 235:       metadata: { durationMs: duration, linesRead: toolCallCount },
 236:     };
 237:   },
 238: 
 239:   async checkPermissions(_input, _context) {
 240:     return { allowed: true };
 241:     // Sub-agent tool calls are themselves permission-checked inside the
 242:     // sub-loop; the user explicitly requested the sub-agent via `task`.
 243:   },
 244: });
