   1: // ============================================================
   2: // Hooks — PreToolUse / PostToolUse interception
   3: // ============================================================
   4: // Hooks let callers observe, block, or rewrite tool calls without
   5: // touching the agent loop. A PreToolUse hook runs before permission
   6: // checks and may deny the call or replace its input. A PostToolUse
   7: // hook runs after execution and may replace the result shown to the
   8: // model. Hooks are matched by tool name (or "*" for all tools).
   9: // ============================================================
  10: 
  11: import type { ToolResult } from "./types.js";
  12: 
  13: export interface PreToolUsePayload {
  14:   toolName: string;
  15:   input: Record<string, unknown>;
  16: }
  17: 
  18: export interface PreToolUseOutcome {
  19:   /** Block the call entirely; `reason` is surfaced to the model. */
  20:   block?: boolean;
  21:   reason?: string;
  22:   /** Replace the tool input before it runs. */
  23:   input?: Record<string, unknown>;
  24: }
  25: 
  26: export interface PostToolUsePayload {
  27:   toolName: string;
  28:   input: Record<string, unknown>;
  29:   result: ToolResult;
  30: }
  31: 
  32: export interface PostToolUseOutcome {
  33:   /** Replace the result shown to the model. */
  34:   result?: ToolResult;
  35: }
  36: 
  37: export interface Hook {
  38:   /** Tool name to match, or "*" for every tool. */
  39:   matcher: string;
  40:   pre?: (payload: PreToolUsePayload) => Promise<PreToolUseOutcome | void> | PreToolUseOutcome | void;
  41:   post?: (payload: PostToolUsePayload) => Promise<PostToolUseOutcome | void> | PostToolUseOutcome | void;
  42: }
  43: 
  44: export class HookRegistry {
  45:   private hooks: Hook[] = [];
  46: 
  47:   register(hook: Hook): void {
  48:     this.hooks.push(hook);
  49:   }
  50: 
  51:   private matching(toolName: string): Hook[] {
  52:     return this.hooks.filter((h) => h.matcher === "*" || h.matcher === toolName);
  53:   }
  54: 
  55:   /**
  56:    * Run PreToolUse hooks in registration order. The first hook to block
  57:    * short-circuits; otherwise input rewrites accumulate.
  58:    */
  59:   async runPre(payload: PreToolUsePayload): Promise<PreToolUseOutcome> {
  60:     let input = payload.input;
  61:     for (const hook of this.matching(payload.toolName)) {
  62:       if (!hook.pre) continue;
  63:       const outcome = await hook.pre({ toolName: payload.toolName, input });
  64:       if (!outcome) continue;
  65:       if (outcome.block) {
  66:         return { block: true, reason: outcome.reason ?? "blocked by hook" };
  67:       }
  68:       if (outcome.input) input = outcome.input;
  69:     }
  70:     return { input };
  71:   }
  72: 
  73:   /**
  74:    * Run PostToolUse hooks in registration order. Result rewrites chain:
  75:    * each hook sees the previous hook's output.
  76:    */
  77:   async runPost(payload: PostToolUsePayload): Promise<PostToolUseOutcome> {
  78:     let result = payload.result;
  79:     for (const hook of this.matching(payload.toolName)) {
  80:       if (!hook.post) continue;
  81:       const outcome = await hook.post({
  82:         toolName: payload.toolName,
  83:         input: payload.input,
  84:         result,
  85:       });
  86:       if (outcome?.result) result = outcome.result;
  87:     }
  88:     return { result };
  89:   }
  90: 
  91:   get size(): number {
  92:     return this.hooks.length;
  93:   }
  94: }
  95: 
