   1: // ============================================================
   2: // Slash Commands — local REPL commands handled before the LLM
   3: // ============================================================
   4: // Input starting with "/" is matched here first. A command can mutate
   5: // session state (messages, model) and print directly; it never hits the
   6: // model unless it explicitly asks the caller to fall through.
   7: // ============================================================
   8: 
   9: import chalk from "chalk";
  10: import { autoCompact } from "./agent-loop.js";
  11: import type { Message, ModelConfig, ModelCaller } from "./types.js";
  12: 
  13: /** Mutable session state a command may read or change. */
  14: export interface CommandContext {
  15:   messages: Message[];
  16:   modelConfig: ModelConfig;
  17:   callModel: ModelCaller;
  18:   workspaceRoot: string;
  19:   sessionId: string;
  20: }
  21: 
  22: export interface CommandResult {
  23:   /** True if the input was a recognized slash command (don't send to LLM). */
  24:   handled: boolean;
  25:   /** True if the REPL should exit. */
  26:   exit?: boolean;
  27: }
  28: 
  29: export interface SlashCommand {
  30:   name: string;
  31:   description: string;
  32:   run: (args: string, ctx: CommandContext) => Promise<void> | void;
  33: }
  34: 
  35: const COMMANDS: SlashCommand[] = [
  36:   {
  37:     name: "help",
  38:     description: "Show available commands",
  39:     run: () => {
  40:       console.log("");
  41:       console.log(chalk.bold("  Commands:"));
  42:       for (const cmd of COMMANDS) {
  43:         console.log(`    ${chalk.cyan("/" + cmd.name).padEnd(20)} ${chalk.gray(cmd.description)}`);
  44:       }
  45:       console.log(`    ${chalk.cyan("@<path>").padEnd(20)} ${chalk.gray("Inject a file's contents into your message")}`);
  46:       console.log(`    ${chalk.cyan("exit").padEnd(20)} ${chalk.gray("Quit")}`);
  47:     },
  48:   },
  49:   {
  50:     name: "clear",
  51:     description: "Clear the conversation history",
  52:     run: (_args, ctx) => {
  53:       ctx.messages.length = 0;
  54:       console.log(chalk.gray("  Conversation cleared."));
  55:     },
  56:   },
  57:   {
  58:     name: "model",
  59:     description: "Show or switch the active model (/model <id>)",
  60:     run: (args, ctx) => {
  61:       const next = args.trim();
  62:       if (!next) {
  63:         console.log(`  Model: ${chalk.cyan(ctx.modelConfig.model)} (${ctx.modelConfig.provider})`);
  64:         return;
  65:       }
  66:       const prev = ctx.modelConfig.model;
  67:       ctx.modelConfig.model = next;
  68:       console.log(chalk.gray(`  Model: ${prev} → ${chalk.cyan(next)}`));
  69:     },
  70:   },
  71:   {
  72:     name: "compact",
  73:     description: "Summarize and compress the conversation now",
  74:     run: async (_args, ctx) => {
  75:       if (ctx.messages.length === 0) {
  76:         console.log(chalk.gray("  Nothing to compact."));
  77:         return;
  78:       }
  79:       const before = ctx.messages.length;
  80:       console.log(chalk.gray("  📦 Compacting..."));
  81:       const compacted = await autoCompact(ctx.messages, ctx.callModel, ctx.modelConfig);
  82:       // Replace contents in place so the caller keeps the same array reference.
  83:       ctx.messages.length = 0;
  84:       ctx.messages.push(...compacted);
  85:       console.log(chalk.gray(`  Compacted ${before} → ${ctx.messages.length} messages.`));
  86:     },
  87:   },
  88:   {
  89:     name: "tokens",
  90:     description: "Show the conversation message count",
  91:     run: (_args, ctx) => {
  92:       console.log(chalk.gray(`  Messages in context: ${ctx.messages.length}`));
  93:     },
  94:   },
  95: ];
  96: 
  97: const COMMAND_MAP = new Map(COMMANDS.map((c) => [c.name, c]));
  98: 
  99: /**
 100:  * Handle a line of input if it is a slash command.
 101:  * Returns handled=false for normal text so the caller sends it to the LLM.
 102:  */
 103: export async function handleSlashCommand(
 104:   input: string,
 105:   ctx: CommandContext,
 106: ): Promise<CommandResult> {
 107:   if (!input.startsWith("/")) return { handled: false };
 108: 
 109:   const [rawName, ...rest] = input.slice(1).split(/\s+/);
 110:   const name = rawName.toLowerCase();
 111:   const args = input.slice(1 + rawName.length).trim();
 112:   const cmd = COMMAND_MAP.get(name);
 113: 
 114:   if (!cmd) {
 115:     console.log(chalk.yellow(`  Unknown command: /${name}. Try /help.`));
 116:     return { handled: true };
 117:   }
 118: 
 119:   await cmd.run(args, ctx);
 120:   return { handled: true };
 121: }
 122: 
 123: export { COMMANDS };
 124: 
