   1: // ============================================================
   2: // @file references — expand "@path" tokens in user input
   3: // ============================================================
   4: // A bare "@src/foo.ts" in the user's message is read from disk and its
   5: // contents appended to the message as context. Paths are resolved inside
   6: // the workspace; escapes and missing files are reported, not injected.
   7: // ============================================================
   8: 
   9: import * as fs from "node:fs";
  10: import * as path from "node:path";
  11: 
  12: // Matches @ followed by a path-like token: letters, digits, /._-~ and
  13: // Windows backslashes. Stops at whitespace. Skips emails (char before @).
  14: const FILE_REF = /(^|\s)@([\w./~\-\\]+)/g;
  15: 
  16: const MAX_FILE_BYTES = 100_000;
  17: 
  18: export interface FileRefResult {
  19:   /** The user text with @refs left intact (model still sees what was typed). */
  20:   text: string;
  21:   /** Resolved file blocks to append as context, or errors to surface. */
  22:   attachments: string[];
  23:   /** Human-readable notes (resolved / skipped) for the CLI to print. */
  24:   notes: string[];
  25: }
  26: 
  27: /**
  28:  * Find @path references in input and read them from the workspace.
  29:  * Returns the original text plus any file contents to append as context.
  30:  */
  31: export function expandFileRefs(input: string, workspaceRoot: string): FileRefResult {
  32:   const attachments: string[] = [];
  33:   const notes: string[] = [];
  34:   const seen = new Set<string>();
  35: 
  36:   for (const match of input.matchAll(FILE_REF)) {
  37:     const ref = match[2];
  38:     if (seen.has(ref)) continue;
  39:     seen.add(ref);
  40: 
  41:     const resolved = path.resolve(workspaceRoot, ref);
  42:     const root = path.resolve(workspaceRoot);
  43:     // Boundary check: must stay inside the workspace.
  44:     if (resolved !== root && !resolved.startsWith(root + path.sep)) {
  45:       notes.push(`  ⚠️  @${ref} is outside the workspace — skipped`);
  46:       continue;
  47:     }
  48: 
  49:     let stat: fs.Stats;
  50:     try {
  51:       stat = fs.statSync(resolved);
  52:     } catch {
  53:       notes.push(`  ⚠️  @${ref} not found — skipped`);
  54:       continue;
  55:     }
  56:     if (!stat.isFile()) {
  57:       notes.push(`  ⚠️  @${ref} is not a file — skipped`);
  58:       continue;
  59:     }
  60:     if (stat.size > MAX_FILE_BYTES) {
  61:       notes.push(`  ⚠️  @${ref} is too large (${stat.size} bytes) — skipped`);
  62:       continue;
  63:     }
  64: 
  65:     try {
  66:       const contents = fs.readFileSync(resolved, "utf-8");
  67:       attachments.push(`<file path="${ref}">\n${contents}\n</file>`);
  68:       notes.push(`  📎 attached @${ref} (${stat.size} bytes)`);
  69:     } catch {
  70:       notes.push(`  ⚠️  @${ref} could not be read — skipped`);
  71:     }
  72:   }
  73: 
  74:   return { text: input, attachments, notes };
  75: }
