   1: // ============================================================
   2: // Native Anthropic Messages API Adapter
   3: // ============================================================
   4: // Converts the project's OpenAI-like internal message/tool format to the
   5: // official Anthropic Messages API shape. Keeps the rest of the agent loop
   6: // provider-agnostic while enabling native Claude features such as prompt
   7: // caching and accurate streaming usage.
   8: // ============================================================
   9: 
  10: import Anthropic from "@anthropic-ai/sdk";
  11: import type {
  12:   Message,
  13:   ModelCaller,
  14:   ModelConfig,
  15:   StreamEvent,
  16:   Tool,
  17: } from "./types.js";
  18: import { DYNAMIC_BOUNDARY } from "./system-prompt.js";
  19: 
  20: // --- Types kept intentionally local ---
  21: 
  22: type AnthropicMessage = {
  23:   role: "user" | "assistant";
  24:   content: string | Array<Record<string, unknown>>;
  25: };
  26: 
  27: type AnthropicTool = {
  28:   name: string;
  29:   description: string;
  30:   input_schema: Tool["inputSchema"];
  31: };
  32: 
  33: // --- System prompt with cache_control ---
  34: 
  35: export function formatSystemForAnthropic(
  36:   systemPrompt: string,
  37: ): string | Array<Record<string, unknown>> {
  38:   const boundaryIndex = systemPrompt.indexOf(DYNAMIC_BOUNDARY);
  39:   if (boundaryIndex === -1) {
  40:     return [
  41:       {
  42:         type: "text",
  43:         text: systemPrompt,
  44:         cache_control: { type: "ephemeral" },
  45:       },
  46:     ];
  47:   }
  48: 
  49:   const stable = systemPrompt.slice(0, boundaryIndex).trimEnd();
  50:   const dynamic = systemPrompt.slice(boundaryIndex).trimStart();
  51:   const blocks: Array<Record<string, unknown>> = [];
  52: 
  53:   if (stable) {
  54:     blocks.push({
  55:       type: "text",
  56:       text: stable,
  57:       cache_control: { type: "ephemeral" },
  58:     });
  59:   }
  60:   if (dynamic) {
  61:     blocks.push({ type: "text", text: dynamic });
  62:   }
  63: 
  64:   return blocks.length === 1 && !stable ? systemPrompt : blocks;
  65: }
  66: 
  67: // --- Message conversion ---
  68: 
  69: export function convertMessagesToAnthropic(messages: Message[]): AnthropicMessage[] {
  70:   const out: AnthropicMessage[] = [];
  71: 
  72:   for (const msg of messages) {
  73:     switch (msg.role) {
  74:       case "system":
  75:         // Anthropic's top-level `system` handles initial system context. If a
  76:         // compacted summary was injected into message history, preserve it as a
  77:         // user-side context block so all Claude models accept the transcript.
  78:         out.push({
  79:           role: "user",
  80:           content: [{ type: "text", text: msg.content }],
  81:         });
  82:         break;
  83: 
  84:       case "user":
  85:         out.push({
  86:           role: "user",
  87:           content: msg.content.map((block) => {
  88:             if (block.type === "text") {
  89:               return { type: "text", text: block.text };
  90:             }
  91:             if (block.type === "image") {
  92:               if (block.source.type === "base64") {
  93:                 // Anthropic represents PDFs as `document` blocks, images as `image`.
  94:                 const isPdf = block.source.media_type === "application/pdf";
  95:                 return {
  96:                   type: isPdf ? "document" : "image",
  97:                   source: {
  98:                     type: "base64",
  99:                     media_type: block.source.media_type,
 100:                     data: block.source.data,
 101:                   },
 102:                 };
 103:               }
 104:               return {
 105:                 type: "image",
 106:                 source: { type: "url", url: block.source.url },
 107:               };
 108:             }
 109:             throw new Error(`Unknown user content block: ${(block as any).type}`);
 110:           }),
 111:         });
 112:         break;
 113: 
 114:       case "assistant": {
 115:         const content: Array<Record<string, unknown>> = [];
 116:         if (msg.content) {
 117:           content.push({ type: "text", text: msg.content });
 118:         }
 119:         for (const call of msg.tool_calls ?? []) {
 120:           content.push({
 121:             type: "tool_use",
 122:             id: call.id,
 123:             name: call.function.name,
 124:             input: JSON.parse(call.function.arguments || "{}"),
 125:           });
 126:         }
 127:         out.push({
 128:           role: "assistant",
 129:           content: content.length > 0 ? content : "",
 130:         });
 131:         break;
 132:       }
 133: 
 134:       case "tool":
 135:         // Anthropic requires tool results in a user message.
 136:         out.push({
 137:           role: "user",
 138:           content: [
 139:             {
 140:               type: "tool_result",
 141:               tool_use_id: msg.tool_call_id,
 142:               content: msg.content,
 143:             },
 144:           ],
 145:         });
 146:         break;
 147:     }
 148:   }
 149: 
 150:   return mergeAdjacentSameRoleMessages(out);
 151: }
 152: 
 153: function mergeAdjacentSameRoleMessages(messages: AnthropicMessage[]): AnthropicMessage[] {
 154:   const merged: AnthropicMessage[] = [];
 155:   for (const msg of messages) {
 156:     const prev = merged[merged.length - 1];
 157:     if (!prev || prev.role !== msg.role) {
 158:       merged.push(msg);
 159:       continue;
 160:     }
 161: 
 162:     const prevBlocks = toContentBlocks(prev.content);
 163:     const nextBlocks = toContentBlocks(msg.content);
 164:     prev.content = [...prevBlocks, ...nextBlocks];
 165:   }
 166:   return merged;
 167: }
 168: 
 169: function toContentBlocks(
 170:   content: string | Array<Record<string, unknown>>,
 171: ): Array<Record<string, unknown>> {
 172:   if (typeof content === "string") {
 173:     return content ? [{ type: "text", text: content }] : [];
 174:   }
 175:   return content;
 176: }
 177: 
 178: // --- Tool conversion ---
 179: 
 180: export function formatToolsForAnthropic(tools: Tool[]): AnthropicTool[] {
 181:   return tools
 182:     .filter((t) => t.isEnabled())
 183:     .map((t) => ({
 184:       name: t.name,
 185:       description: t.promptDescription,
 186:       input_schema: t.inputSchema,
 187:     }));
 188: }
 189: 
 190: // --- Native Anthropic streaming caller ---
 191: 
 192: export const anthropicCaller: ModelCaller = async function* (
 193:   messages: Message[],
 194:   tools: Tool[],
 195:   systemPrompt: string,
 196:   config: ModelConfig,
 197: ): AsyncGenerator<StreamEvent> {
 198:   const client = new Anthropic({
 199:     apiKey: config.apiKey,
 200:     baseURL: config.baseURL,
 201:   });
 202: 
 203:   const stream = client.messages.stream({
 204:     model: config.model || "claude-opus-4-8",
 205:     max_tokens: config.maxTokens ?? 16_000,
 206:     system: formatSystemForAnthropic(systemPrompt) as any,
 207:     messages: convertMessagesToAnthropic(messages) as any,
 208:     tools: tools.length > 0 ? (formatToolsForAnthropic(tools) as any) : undefined,
 209:     // Claude 4.8 benefits from adaptive thinking; harmlessly omitted when the
 210:     // caller uses a non-Claude provider because this adapter only runs for
 211:     // provider="anthropic".
 212:     thinking: config.options?.thinking ?? { type: "adaptive" },
 213:     output_config: config.options?.output_config ?? { effort: "high" },
 214:   } as any);
 215: 
 216:   stream.on("text", (text) => {
 217:     void text;
 218:   });
 219: 
 220:   for await (const event of stream) {
 221:     if (event.type === "content_block_delta") {
 222:       if (event.delta.type === "text_delta") {
 223:         yield { type: "text_delta", delta: event.delta.text };
 224:       }
 225:       // `input_json_delta` is accumulated by the SDK finalMessage helper;
 226:       // no partial tool input event is needed by the current agent loop.
 227:     }
 228:   }
 229: 
 230:   const final = await stream.finalMessage();
 231: 
 232:   for (const block of final.content as any[]) {
 233:     if (block.type === "tool_use") {
 234:       yield {
 235:         type: "tool_use",
 236:         id: block.id,
 237:         name: block.name,
 238:         input: block.input ?? {},
 239:       };
 240:     }
 241:   }
 242: 
 243:   yield {
 244:     type: "done",
 245:     usage: {
 246:       input_tokens:
 247:         (final.usage as any).input_tokens +
 248:         ((final.usage as any).cache_creation_input_tokens ?? 0) +
 249:         ((final.usage as any).cache_read_input_tokens ?? 0),
 250:       output_tokens: (final.usage as any).output_tokens ?? 0,
 251:     },
 252:     finish_reason: final.stop_reason ?? "end_turn",
 253:   };
 254: };
