   1: // ============================================================
   2: // CLI Renderer — terminal presentation helpers
   3: // ============================================================
   4: // Keeps CLI display logic out of cli.ts: streaming markdown-ish output,
   5: // tool progress/result rendering, and permission prompt formatting.
   6: // ============================================================
   7: 
   8: import chalk from "chalk";
   9: import type { ToolExecutionResult } from "./types.js";
  10: 
  11: export class StreamingRenderer {
  12:   private lineBuffer = "";
  13:   private inCodeBlock = false;
  14: 
  15:   write(delta: string): void {
  16:     this.lineBuffer += delta;
  17: 
  18:     let newlineIndex: number;
  19:     while ((newlineIndex = this.lineBuffer.indexOf("\n")) !== -1) {
  20:       const line = this.lineBuffer.slice(0, newlineIndex);
  21:       this.lineBuffer = this.lineBuffer.slice(newlineIndex + 1);
  22:       process.stdout.write(this.formatLine(line) + "\n");
  23:     }
  24:   }
  25: 
  26:   flush(): void {
  27:     if (this.lineBuffer.length > 0) {
  28:       process.stdout.write(this.formatLine(this.lineBuffer));
  29:       this.lineBuffer = "";
  30:     }
  31:   }
  32: 
  33:   private formatLine(line: string): string {
  34:     const trimmed = line.trimStart();
  35: 
  36:     if (trimmed.startsWith("```")) {
  37:       this.inCodeBlock = !this.inCodeBlock;
  38:       return chalk.gray(line);
  39:     }
  40: 
  41:     if (this.inCodeBlock) {
  42:       return chalk.cyan(line);
  43:     }
  44: 
  45:     if (/^#{1,6}\s/.test(trimmed)) {
  46:       return chalk.bold.cyan(line);
  47:     }
  48: 
  49:     if (/^[-*+]\s+/.test(trimmed)) {
  50:       return line.replace(/^([\s]*[-*+]\s+)/, chalk.gray("$1"));
  51:     }
  52: 
  53:     if (/^\d+\.\s+/.test(trimmed)) {
  54:       return line.replace(/^([\s]*\d+\.\s+)/, chalk.gray("$1"));
  55:     }
  56: 
  57:     return line;
  58:   }
  59: }
  60: 
  61: export function renderToolStart(name: string, input?: Record<string, unknown>): void {
  62:   const detail = formatToolDetail(input);
  63:   process.stdout.write(`\n${chalk.blue("  🔧")} ${chalk.bold(name)}`);
  64:   if (detail) process.stdout.write(chalk.gray(` — ${detail}`));
  65:   process.stdout.write("\n");
  66: }
  67: 
  68: export function renderToolResult(result: ToolExecutionResult): void {
  69:   const duration =
  70:     typeof result.durationMs === "number" ? chalk.gray(` (${result.durationMs}ms)`) : "";
  71: 
  72:   if (result.error) {
  73:     console.log(`${chalk.red("  ❌")} ${chalk.bold(result.toolName)}${duration}: ${chalk.red(result.error)}`);
  74:     return;
  75:   }
  76: 
  77:   console.log(`${chalk.green("  ✅")} ${chalk.bold(result.toolName)}${duration}`);
  78:   const rendered = renderFormattedToolOutput(result.formatted);
  79:   if (rendered) {
  80:     console.log(indent(rendered, "     "));
  81:   }
  82: }
  83: 
  84: export function renderPermissionPrompt(
  85:   toolName: string,
  86:   input: Record<string, unknown>,
  87:   riskHint?: string,
  88: ): void {
  89:   console.log("");
  90:   console.log(chalk.yellow(`  ⚠️  Permission required: ${toolName}`));
  91:   if (riskHint) {
  92:     console.log(chalk.yellow(`     Risk: ${riskHint}`));
  93:   }
  94:   const detail = formatToolDetail(input);
  95:   if (detail) {
  96:     console.log(chalk.gray(`     ${detail}`));
  97:   }
  98:   console.log(chalk.gray("     y = allow once, a = always for this tool+target, n/Enter = deny"));
  99: }
 100: 
 101: function renderFormattedToolOutput(text: string): string {
 102:   const lines = text.split("\n");
 103:   const MAX_LINES = 24;
 104:   const clipped = lines.slice(0, MAX_LINES);
 105:   const wasClipped = lines.length > MAX_LINES;
 106: 
 107:   const rendered = clipped
 108:     .map((line) => {
 109:       if (line.startsWith("+ ")) return chalk.green(line);
 110:       if (line.startsWith("- ")) return chalk.red(line);
 111:       if (line.startsWith("Error:")) return chalk.red(line);
 112:       if (line.includes("[... result too long, truncated]")) return chalk.gray(line);
 113:       return line;
 114:     })
 115:     .join("\n");
 116: 
 117:   return rendered + (wasClipped ? chalk.gray("\n... output clipped in CLI preview") : "");
 118: }
 119: 
 120: function formatToolDetail(input?: Record<string, unknown>): string {
 121:   if (!input) return "";
 122:   if (typeof input.command === "string") return truncate(input.command, 120);
 123:   if (typeof input.filePath === "string") return truncate(input.filePath, 120);
 124:   if (typeof input.pattern === "string") return truncate(input.pattern, 120);
 125:   if (typeof input.url === "string") return truncate(input.url, 120);
 126:   return "";
 127: }
 128: 
 129: function truncate(value: string, max: number): string {
 130:   return value.length <= max ? value : value.slice(0, max - 1) + "…";
 131: }
 132: 
 133: function indent(text: string, prefix: string): string {
 134:   return text
 135:     .split("\n")
 136:     .map((line) => prefix + line)
 137:     .join("\n");
 138: }
