   1: // ============================================================
   2: // WebFetch Tool — Fetch and extract web page content
   3: // ============================================================
   4: // Fetches a URL, strips HTML, and returns plain text content
   5: // for the LLM to analyze based on a user's fetchInfo prompt.
   6: // ============================================================
   7: 
   8: import type { Tool, ToolContext, ToolResult } from "./types.js";
   9: import { createTool } from "./tool-registry.js";
  10: 
  11: // --- Constants ---
  12: 
  13: const MAX_CONTENT_LENGTH = 100_000; // 100KB output
  14: const MAX_RESPONSE_SIZE = 5 * 1024 * 1024; // 5MB max download
  15: const TIMEOUT_MS = 15_000; // 15 seconds
  16: const MAX_REDIRECTS = 5;
  17: 
  18: // Private/internal network patterns to block (SSRF prevention)
  19: const BLOCKED_HOSTS = [
  20:   /^localhost$/i,
  21:   /^127\.\d+\.\d+\.\d+$/,
  22:   /^10\.\d+\.\d+\.\d+$/,
  23:   /^172\.(1[6-9]|2\d|3[01])\.\d+\.\d+$/,
  24:   /^192\.168\.\d+\.\d+$/,
  25:   /^0\.0\.0\.0$/,
  26:   /^::1$/,
  27:   /^fc00:/i,
  28:   /^fe80:/i,
  29: ];
  30: 
  31: // --- Input ---
  32: 
  33: interface WebFetchInput {
  34:   url: string;
  35:   fetchInfo: string;
  36:   [key: string]: unknown;
  37: }
  38: 
  39: // --- Helpers ---
  40: 
  41: function isBlockedHost(hostname: string): boolean {
  42:   // Strip brackets from IPv6 addresses
  43:   const host = hostname.replace(/^\[|\]$/g, "");
  44:   return BLOCKED_HOSTS.some((pattern) => pattern.test(host));
  45: }
  46: 
  47: function stripHtml(html: string): string {
  48:   // Remove scripts and styles completely
  49:   let text = html
  50:     .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, "")
  51:     .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, "")
  52:     .replace(/<noscript[^>]*>[\s\S]*?<\/noscript>/gi, "");
  53: 
  54:   // Replace block elements with newlines
  55:   text = text.replace(
  56:     /<\/(div|p|h[1-6]|li|tr|article|section|header|footer|main|nav|aside|table|br|hr)[^>]*>/gi,
  57:     "\n",
  58:   );
  59:   text = text.replace(/<br[^>]*\/?>/gi, "\n");
  60:   text = text.replace(/<hr[^>]*\/?>/gi, "\n---\n");
  61: 
  62:   // Remove remaining HTML tags
  63:   text = text.replace(/<[^>]+>/g, "");
  64: 
  65:   // Decode common HTML entities
  66:   text = text
  67:     .replace(/&amp;/g, "&")
  68:     .replace(/&lt;/g, "<")
  69:     .replace(/&gt;/g, ">")
  70:     .replace(/&quot;/g, '"')
  71:     .replace(/&#39;/g, "'")
  72:     .replace(/&nbsp;/g, " ")
  73:     .replace(/&#(\d+);/g, (_, d) => String.fromCharCode(Number(d)));
  74: 
  75:   // Collapse whitespace
  76:   text = text
  77:     .split("\n")
  78:     .map((line) => line.trim())
  79:     .filter((line) => line.length > 0)
  80:     .join("\n");
  81: 
  82:   return text;
  83: }
  84: 
  85: // --- Tool ---
  86: 
  87: export const WebFetchTool: Tool = createTool<WebFetchInput>({
  88:   name: "web_fetch",
  89:   description: "Fetch a web page and extract its content",
  90:   promptDescription:
  91:     "Fetch content from a URL and analyze it. " +
  92:     "Provide url (must be http/https) and fetchInfo (what you want to extract from the page). " +
  93:     "The tool returns plain text content (HTML tags stripped). " +
  94:     "Use this to read documentation, check API responses, or research topics.",
  95:   inputSchema: {
  96:     type: "object",
  97:     properties: {
  98:       url: {
  99:         type: "string",
 100:         description: "The URL to fetch (must start with http:// or https://)",
 101:       },
 102:       fetchInfo: {
 103:         type: "string",
 104:         description: "What information you want to extract from this page",
 105:       },
 106:     },
 107:     required: ["url", "fetchInfo"],
 108:   },
 109:   isReadOnly: true,
 110:   isConcurrencySafe: true,
 111: 
 112:   async call(input, _context): Promise<ToolResult> {
 113:     const url = input.url?.trim();
 114:     const fetchInfo = input.fetchInfo?.trim();
 115: 
 116:     if (!url) {
 117:       return { content: "", error: "url is required" };
 118:     }
 119:     if (!fetchInfo) {
 120:       return { content: "", error: "fetchInfo is required" };
 121:     }
 122: 
 123:     // --- Validate URL ---
 124: 
 125:     let parsed: URL;
 126:     try {
 127:       parsed = new URL(url);
 128:     } catch {
 129:       return {
 130:         content: "",
 131:         error: `Invalid URL: "${url}". Must be a valid http/https URL.`,
 132:       };
 133:     }
 134: 
 135:     if (!["http:", "https:"].includes(parsed.protocol)) {
 136:       return {
 137:         content: "",
 138:         error: `Unsupported protocol: "${parsed.protocol}". Only http and https are allowed.`,
 139:       };
 140:     }
 141: 
 142:     // --- SSRF check ---
 143: 
 144:     if (isBlockedHost(parsed.hostname)) {
 145:       return {
 146:         content: "",
 147:         error: `Access denied: "${parsed.hostname}" is an internal/private address.`,
 148:       };
 149:     }
 150: 
 151:     // --- Fetch ---
 152: 
 153:     const controller = new AbortController();
 154:     const timeoutId = setTimeout(() => controller.abort(), TIMEOUT_MS);
 155: 
 156:     try {
 157:       const response = await fetch(url, {
 158:         method: "GET",
 159:         headers: {
 160:           "User-Agent":
 161:             "ClaudeCodeReplica/1.0 (AI coding assistant; +https://github.com/claude-code-replica)",
 162:           Accept: "text/html, text/plain, application/json, */*",
 163:         },
 164:         redirect: "follow",
 165:         signal: controller.signal,
 166:       });
 167: 
 168:       clearTimeout(timeoutId);
 169: 
 170:       // Check content type
 171:       const contentType = response.headers.get("content-type") || "";
 172: 
 173:       // Read response (with size limit)
 174:       let rawBody: string;
 175:       try {
 176:         const buf = await readLimited(response, MAX_RESPONSE_SIZE);
 177:         rawBody = new TextDecoder().decode(buf);
 178:       } catch (err: any) {
 179:         if (err.name === "AbortError") {
 180:           return { content: "", error: `Request timed out after ${TIMEOUT_MS / 1000}s` };
 181:         }
 182:         return { content: "", error: `Failed to read response: ${err.message}` };
 183:       }
 184: 
 185:       let content: string;
 186: 
 187:       if (contentType.includes("text/html")) {
 188:         content = stripHtml(rawBody);
 189:       } else if (
 190:         contentType.includes("text/") ||
 191:         contentType.includes("application/json") ||
 192:         contentType.includes("application/xml")
 193:       ) {
 194:         // For non-HTML text content, use as-is (but strip potential HTML)
 195:         content = rawBody;
 196:       } else {
 197:         return {
 198:           content: "",
 199:           error: `Unsupported content type: "${contentType}". Only text formats are supported.`,
 200:         };
 201:       }
 202: 
 203:       // Truncate
 204:       const truncated = content.length > MAX_CONTENT_LENGTH;
 205:       if (truncated) {
 206:         content = content.slice(0, MAX_CONTENT_LENGTH);
 207:       }
 208: 
 209:       const header = [
 210:         `URL: ${url}`,
 211:         `Status: ${response.status} ${response.statusText}`,
 212:         `Content-Type: ${contentType}`,
 213:         `Content-Length: ${content.length} chars${truncated ? " (truncated)" : ""}`,
 214:         ``,
 215:         `--- Content (extract "${fetchInfo}") ---`,
 216:         ``,
 217:       ].join("\n");
 218: 
 219:       return {
 220:         content: header + content,
 221:         truncated,
 222:         metadata: {
 223:           linesRead: content.split("\n").length,
 224:         },
 225:       };
 226:     } catch (err: any) {
 227:       clearTimeout(timeoutId);
 228:       if (err.name === "AbortError") {
 229:         return { content: "", error: `Request timed out after ${TIMEOUT_MS / 1000}s` };
 230:       }
 231:       return { content: "", error: `Fetch failed: ${err.message}` };
 232:     }
 233:   },
 234: 
 235:   async checkPermissions(_input, _context) {
 236:     return { allowed: true }; // Read-only — auto-approved
 237:   },
 238: });
 239: 
 240: // --- Helper: Read response body with size limit ---
 241: 
 242: async function readLimited(
 243:   response: Response,
 244:   maxSize: number,
 245: ): Promise<Uint8Array> {
 246:   const reader = response.body?.getReader();
 247:   if (!reader) {
 248:     throw new Error("Response body is not readable");
 249:   }
 250: 
 251:   const chunks: Uint8Array[] = [];
 252:   let totalSize = 0;
 253: 
 254:   while (true) {
 255:     const { done, value } = await reader.read();
 256:     if (done) break;
 257:     totalSize += value.length;
 258:     if (totalSize > maxSize) {
 259:       reader.cancel();
 260:       throw new Error(`Response exceeds maximum size of ${maxSize} bytes`);
 261:     }
 262:     chunks.push(value);
 263:   }
 264: 
 265:   // Combine chunks
 266:   const result = new Uint8Array(totalSize);
 267:   let offset = 0;
 268:   for (const chunk of chunks) {
 269:     result.set(chunk, offset);
 270:     offset += chunk.length;
 271:   }
 272:   return result;
 273: }
