   1: // ============================================================
   2: // WebSearch Tool — search the web and return result snippets
   3: // ============================================================
   4: // Provider-agnostic: by default it queries DuckDuckGo's no-key HTML
   5: // endpoint and parses the result list into title/url/snippet rows for
   6: // the LLM to synthesize. No API key required.
   7: // ============================================================
   8: 
   9: import type { Tool, ToolResult } from "./types.js";
  10: import { createTool } from "./tool-registry.js";
  11: 
  12: const TIMEOUT_MS = 15_000;
  13: const MAX_RESULTS = 10;
  14: const SEARCH_ENDPOINT = "https://html.duckduckgo.com/html/";
  15: 
  16: interface WebSearchInput {
  17:   query: string;
  18:   [key: string]: unknown;
  19: }
  20: 
  21: interface SearchResult {
  22:   title: string;
  23:   url: string;
  24:   snippet: string;
  25: }
  26: 
  27: function decodeEntities(s: string): string {
  28:   return s
  29:     .replace(/<[^>]+>/g, "")
  30:     .replace(/&amp;/g, "&")
  31:     .replace(/&lt;/g, "<")
  32:     .replace(/&gt;/g, ">")
  33:     .replace(/&quot;/g, '"')
  34:     .replace(/&#x27;|&#39;/g, "'")
  35:     .replace(/&nbsp;/g, " ")
  36:     .replace(/&#(\d+);/g, (_, d) => String.fromCharCode(Number(d)))
  37:     .trim();
  38: }
  39: 
  40: // DuckDuckGo wraps real URLs in a redirect like
  41: // //duckduckgo.com/l/?uddg=<encoded>. Unwrap it when present.
  42: function unwrapUrl(href: string): string {
  43:   try {
  44:     const u = new URL(href, "https://duckduckgo.com");
  45:     const target = u.searchParams.get("uddg");
  46:     return target ? decodeURIComponent(target) : href;
  47:   } catch {
  48:     return href;
  49:   }
  50: }
