  52: /** Parse DuckDuckGo HTML results. Exported for testing. */
  53: export function parseSearchResults(html: string, limit = MAX_RESULTS): SearchResult[] {
  54:   const results: SearchResult[] = [];
  55:   // Each result link: <a ... class="result__a" href="...">Title</a>
  56:   const linkRe = /<a[^>]*class="[^"]*result__a[^"]*"[^>]*href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/gi;
  57:   // Snippets: <a ... class="result__snippet" ...>snippet</a>
  58:   const snippetRe = /<a[^>]*class="[^"]*result__snippet[^"]*"[^>]*>([\s\S]*?)<\/a>/gi;
  59: 
  60:   const snippets: string[] = [];
  61:   let sm: RegExpExecArray | null;
  62:   while ((sm = snippetRe.exec(html)) !== null) {
  63:     snippets.push(decodeEntities(sm[1]));
  64:   }
  65: 
  66:   let lm: RegExpExecArray | null;
  67:   let i = 0;
  68:   while ((lm = linkRe.exec(html)) !== null && results.length < limit) {
  69:     const url = unwrapUrl(lm[1]);
  70:     const title = decodeEntities(lm[2]);
  71:     if (!title || !url) {
  72:       i++;
  73:       continue;
  74:     }
  75:     results.push({ title, url, snippet: snippets[i] ?? "" });
  76:     i++;
  77:   }
  78:   return results;
  79: }
