  81: export const WebSearchTool: Tool = createTool<WebSearchInput>({
  82:   name: "web_search",
  83:   description: "Search the web and return result snippets",
  84:   promptDescription:
  85:     "Search the web for current information. Provide query (the search terms). " +
  86:     "Returns a ranked list of results with titles, URLs, and snippets. " +
  87:     "Use this to find documentation, recent events, or facts beyond your training data, " +
  88:     "then optionally follow up with web_fetch to read a specific result in full.",
  89:   inputSchema: {
  90:     type: "object",
  91:     properties: {
  92:       query: {
  93:         type: "string",
  94:         description: "The search query",
  95:       },
  96:     },
  97:     required: ["query"],
  98:   },
  99:   isReadOnly: true,
 100:   isConcurrencySafe: true,
 101: 
 102:   async call(input): Promise<ToolResult> {
 103:     const query = input.query?.trim();
 104:     if (!query) {
 105:       return { content: "", error: "query is required" };
 106:     }
 107: 
 108:     const controller = new AbortController();
 109:     const timeoutId = setTimeout(() => controller.abort(), TIMEOUT_MS);
 110: 
 111:     try {
 112:       const response = await fetch(SEARCH_ENDPOINT, {
 113:         method: "POST",
 114:         headers: {
 115:           "User-Agent":
 116:             "ClaudeCodeReplica/1.0 (AI coding assistant; +https://github.com/claude-code-replica)",
 117:           "Content-Type": "application/x-www-form-urlencoded",
 118:           Accept: "text/html",
 119:         },
 120:         body: new URLSearchParams({ q: query }).toString(),
 121:         signal: controller.signal,
 122:       });
 123:       clearTimeout(timeoutId);
 124: 
 125:       if (!response.ok) {
 126:         return {
 127:           content: "",
 128:           error: `Search failed: ${response.status} ${response.statusText}`,
 129:         };
 130:       }
 131: 
 132:       const html = await response.text();
 133:       const results = parseSearchResults(html);
 134: 
 135:       if (results.length === 0) {
 136:         return { content: `No results found for "${query}".` };
 137:       }
 138: 
 139:       const body = results
 140:         .map(
 141:           (r, idx) =>
 142:             `${idx + 1}. ${r.title}\n   ${r.url}${r.snippet ? `\n   ${r.snippet}` : ""}`,
 143:         )
 144:         .join("\n\n");
 145: 
 146:       return {
 147:         content: `Search results for "${query}":\n\n${body}`,
 148:         metadata: { linesRead: results.length },
 149:       };
 150:     } catch (err: any) {
 151:       clearTimeout(timeoutId);
 152:       if (err.name === "AbortError") {
 153:         return { content: "", error: `Search timed out after ${TIMEOUT_MS / 1000}s` };
 154:       }
