   1: // ============================================================
   2: // CLI input reader — readline wrapper with EOF-safe semantics
   3: // ============================================================
   4: // readline.question throws ERR_USE_AFTER_CLOSE if stdin has already closed
   5: // (piped input drained, Ctrl+D, etc.). This wrapper converts EOF into null so
   6: // the REPL can exit cleanly.
   7: // ============================================================
   8: 
   9: import type * as readline from "node:readline";
  10: 
  11: export interface CliInputReader {
  12:   askQuestion(prompt: string): Promise<string | null>;
  13:   readInput(): Promise<string | null>;
  14:   isClosed(): boolean;
  15: }
  16: 
  17: export function createCliInputReader(
  18:   rl: readline.Interface,
  19: ): CliInputReader {
  20:   let stdinClosed = false;
  21:   rl.on("close", () => {
  22:     stdinClosed = true;
  23:   });
  24: 
  25:   const askQuestion = (prompt: string): Promise<string | null> => {
  26:     if (stdinClosed) return Promise.resolve(null);
  27:     return new Promise((resolve) => {
  28:       let settled = false;
  29:       const onClose = () => {
  30:         if (!settled) {
  31:           settled = true;
  32:           resolve(null);
  33:         }
  34:       };
  35:       rl.once("close", onClose);
  36:       rl.question(prompt, (answer) => {
  37:         settled = true;
  38:         rl.removeListener("close", onClose);
  39:         resolve(answer);
  40:       });
  41:     });
  42:   };
  43: 
  44:   const readInput = async (): Promise<string | null> => {
  45:     const first0 = await askQuestion("\n> ");
  46:     if (first0 === null) return null;
  47:     let first = first0;
  48:     if (!first) return first;
  49: 
  50:     const lines: string[] = [];
  51:     let inFence = /^```/.test(first.trimStart());
  52: 
  53:     const continues = (line: string) => line.endsWith("\\");
  54:     let pendingContinuation = continues(first) && !inFence;
  55:     if (pendingContinuation) first = first.slice(0, -1);
  56:     lines.push(first);
  57: 
  58:     while (inFence || pendingContinuation) {
  59:       const next = await askQuestion(inFence ? "… " : "… ");
  60:       if (next === null) break;
  61:       if (inFence) {
  62:         lines.push(next);
  63:         if (/^```/.test(next.trimStart())) inFence = false;
  64:       } else {
  65:         pendingContinuation = continues(next);
  66:         lines.push(pendingContinuation ? next.slice(0, -1) : next);
  67:       }
  68:     }
  69: 
  70:     return lines.join("\n");
  71:   };
  72: 
  73:   return {
  74:     askQuestion,
  75:     readInput,
  76:     isClosed: () => stdinClosed,
  77:   };
  78: }
