   1: // ============================================================
   2: // CLI Error Formatting — concise provider/API errors
   3: // ============================================================
   4: // SDK errors often contain large headers/request objects. Terminal users need
   5: // the action item, not a dumped object. This formatter keeps the detail short
   6: // and avoids printing secrets or noisy response metadata.
   7: // ============================================================
   8: 
   9: export function formatCliError(error: unknown): string {
  10:   const anyErr = error as any;
  11:   const status = anyErr?.status;
  12:   const type = anyErr?.type || anyErr?.error?.type || anyErr?.error?.error?.type;
  13:   const message =
  14:     anyErr?.error?.message ||
  15:     anyErr?.error?.error?.message ||
  16:     anyErr?.message ||
  17:     String(error);
  18: 
  19:   if (status === 401 || status === 403) {
  20:     return `Authentication/permission error (${status}). Check LLM_API_KEY, provider, base URL, and account access. ${message}`;
  21:   }
  22: 
  23:   if (status === 429) {
  24:     return `Rate limit error (429). Slow down or raise your provider quota. ${message}`;
  25:   }
  26: 
  27:   if (status === 400 && /context|token|maximum/i.test(message)) {
  28:     return `Context/token limit error (400). Try /compact or a smaller request. ${message}`;
  29:   }
  30: 
  31:   if (typeof status === "number" && status >= 500) {
  32:     return `Provider server error (${status}). Retry later or switch provider. ${message}`;
  33:   }
  34: 
  35:   if (type) {
  36:     return `Provider error${status ? ` (${status})` : ""} [${type}]: ${message}`;
  37:   }
  38: 
  39:   if (error instanceof Error) {
  40:     return error.message;
  41:   }
  42: 
  43:   return String(error);
  44: }
